import React, { useState } from 'react';

// Create the App component here
function App() {
  // Initialize count state here
  const [count, setCount] = useState<number>(0);

  // Define increment handler here
  const increment = () => {
    setCount(prev => prev + 1);
  };

  return (
    <div>
      <h1>React.memo Demo</h1>
      {/* Add button with onClick handler here */}
      <button onClick={increment}>Increment: {count}</button>
      {/* Add Child component with static prop here */}
      <Child />
    </div>
  );
}

// Create Child component here

function Child() {
  // Add console.log here
  console.log('Child rendered');
  return <div>Child component</div>;
}

// Wrap Child with React.memo here
const MemoizedChild = React.memo(Child);

export default App;

